import { ASSET_TYPES, assetTypeSpecs, FRAMEWORK_VERSION } from '../axf/core';
import { Button, Chip, Container, Icon, useAxfState, useRuntime } from '../axf/react';

/** Starter view generated by `axf init`. Replace it with your app. */
export function Home() {
  const rt = useRuntime();
  useAxfState();
  const m = rt.manifest;

  return (
    <div className="fx-stack fx-stack--lg">
      <header className="fx-pagehead">
        <div>
          <p className="fx-eyebrow">Initialized with AmberX AXF {FRAMEWORK_VERSION}</p>
          <h1>{m.app.name} is ready</h1>
          <p className="fx-muted">
            This boilerplate was generated by the build engine. The layout, themes, menus, toolbar, overlays and controls you see are all
            assets — swap any of them and every AmberX AXF app built from the same defaults changes the same way.
          </p>
        </div>
        <div className="fx-row fx-row--wrap">
          <Button tone="primary" icon="layers" onClick={() => rt.navigate('assets')}>Open hot-swap studio</Button>
          <Button icon="shuffle" requires="assets.swap" onClick={() => rt.randomize()}>Randomize</Button>
        </div>
      </header>

      <div className="fx-grid">
        <Container title="Project" icon="package">
          <table className="fx-table">
            <tbody>
              <tr><th>App id</th><td className="fx-mono">{m.app.id}</td></tr>
              <tr><th>Version</th><td>{m.app.version}</td></tr>
              <tr><th>Template</th><td>{m.framework.template}</td></tr>
              <tr><th>Targets</th><td>{m.targets.join(', ')}</td></tr>
              <tr><th>Initialized</th><td>{m.initializedAt ? new Date(m.initializedAt).toLocaleDateString() : '—'}</td></tr>
            </tbody>
          </table>
        </Container>

        <Container title="Baked structure" icon="folder">
          <ul className="home-tree">
            {(m.structure ?? []).map((e) => (
              <li key={e.path}>
                <span className="fx-mono">{e.path}</span>
                <span className="fx-muted fx-small">{e.purpose}</span>
              </li>
            ))}
          </ul>
        </Container>

        <Container title="Next steps" icon="terminal">
          <ol className="home-steps">
            <li>Edit <code>src/views/Home.tsx</code> — this screen.</li>
            <li>Add a view in <code>src/App.tsx</code>; nav assets pick it up by id.</li>
            <li>
              Clone an asset: <code>node framework/cli/axf.mjs new-asset color-theme my-theme --from amber-ember</code>
            </li>
            <li>Check conformance: <code>axf validate</code></li>
          </ol>
        </Container>
      </div>

      <Container title="Active assets" icon="layers" actions={<Chip tone="accent">{rt.getState().swaps} swaps</Chip>}>
        <div className="home-slots">
          {ASSET_TYPES.map((t) => (
            <button key={t} type="button" className="home-slot" onClick={() => rt.swap(t, 'next')} title={`Tap to swap ${assetTypeSpecs[t].label}`}>
              <Icon name={assetTypeSpecs[t].icon} size={15} />
              <span className="fx-muted fx-small">{assetTypeSpecs[t].label}</span>
              <strong>{rt.asset(t).name}</strong>
            </button>
          ))}
        </div>
      </Container>

      <style>{`
        .home-tree, .home-steps { margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--fx-dens-gap-2xl); }
        .home-tree { list-style: none; }
        .home-tree li { display: flex; flex-direction: column; gap: 1px; }
        .home-steps { padding-left: var(--fx-dens-gap-3xl); font-size: var(--fx-type-scale-md); }
        .home-steps code { word-break: break-word; }
        .home-slots { display: grid; gap: var(--fx-dens-gap-xl); grid-template-columns: repeat(auto-fill, minmax(min(100%, 170px), 1fr)); }
        .home-slot { display: grid; grid-template-columns: auto 1fr; column-gap: var(--fx-dens-gap-xl); align-items: center; text-align: left;
          padding: var(--fx-dens-gap-2xl) var(--fx-dens-gap-2xl); border: var(--fx-border-w) solid var(--fx-border); border-radius: var(--fx-radius-md); background: var(--fx-surface2); }
        .home-slot:hover { border-color: var(--fx-accent); }
        .home-slot svg { grid-row: span 2; color: var(--fx-accent); }
      `}</style>
    </div>
  );
}
